gx11: {level: "B2", goals: ["أعلّل بسبب معلوم بـ da.", "أؤكّد بسبب مضيف بـ zumal."], what: "da = بما أنّ (سبب معلوم): Da alle zustimmen, stimmen wir ab؛ zumal = لا سيّما أنّ (سبب مضيف).", why: "تنويع التعليل يرفع مستوى الكتابة الرسمية.", when: ["معلوم: Da die Quelle fehlt, stoppen wir.", "مضيف: Er bleibt, zumal er eingeladen ist.", "نفي: Da niemand widerspricht, gilt der Beschluss."], how: ["1- da/zumal + فعل أخير.", "2- denn رئيسية ولا تفتتح الجملة.", "3- المتطلّب المسبق: weil/denn."], examples: [["Da alle zustimmen, tagen wir sofort.", "بما أنّ الجميع موافق نجتمع فورًا.", ""], ["Er bleibt gelassen, zumal er recht hat.", "يبقى هادئًا لا سيّما أنّه محقّ.", ""]], daily: [["Da du da bist, hilf mir.", "بما أنّك هنا ساعدني.", ""]], notes: ["denn لا تبدأ الجملة.", "zumal يضيف سببًا ثانيًا."], mistakes: [{w: "Denn alle zustimmen, tagen wir.", r: "Da alle zustimmen, tagen wir.", why: "افتتاح السبب يتطلّب da/weil لا denn."}], compare: "denn (رئيسية وسط) ← da (فرعية مفتتحة). قارن درس weil.", summary: "da للمعلوم، zumal للمضيف.", drill: [{t: "أي أداة تعني لا سيّما أنّ؟", opts: ["denn", "zumal", "aber"], correct: 1, why: "zumal = لا سيّما أنّ."}], review: {rule: "التعليل بـ da/zumal.", words: "da, zumal, denn", example: "Da alle zustimmen", mistake: "denn في الافتتاح.", q: "علّل: بما أنّ المصدر غائب."}, relWords: ["Medienkompetenz", "Persönlichkeitsrecht", "Urheberrechtsverletzung"]},
